CREATE TABLE monthly (month TEXT PRIMARY KEY, revenue REAL);
INSERT INTO monthly VALUES
 ('2026-01',100.0),('2026-02',150.0),('2026-03',120.0);

questions.solution:
SELECT month, revenue,
  ROUND((revenue - LAG(revenue) OVER (ORDER BY month)) * 1.0 / LAG(revenue) OVER (ORDER BY month), 4) AS mom_growth
FROM monthly ORDER BY month;

