questions.solution:
WITH ranked AS (
  SELECT category, product, revenue,
         ROW_NUMBER() OVER (PARTITION BY category ORDER BY revenue DESC) AS rn
  FROM salescat
)
SELECT category, product, revenue FROM ranked WHERE rn <= 2 ORDER BY category, rn;

