WITH s AS (SELECT user_id, MIN(ts) AS t FROM events WHERE event = 'signup' GROUP BY user_id),
     p AS (SELECT user_id, MIN(ts) AS t FROM events WHERE event = 'purchase' GROUP BY user_id)
SELECT s.user_id FROM s JOIN p ON s.user_id = p.user_id AND p.t > s.t ORDER BY s.user_id;

