INSERT INTO raw VALUES
 (1,'x','2026-01-01'),
 (1,'y','2026-02-01'),
 (2,'p','2026-01-15');

questions.solution:
WITH d AS (
  SELECT user_id, val, updated,
         ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY updated DESC) AS rn
  FROM raw
)
SELECT user_id, val, updated FROM d WHERE rn = 1 ORDER BY user_id;
